  "checks": {
    "requirement_fit": {
      "status": "pass",
      "evidence": "官方要求逐字（官方佐證表第 4 頁，I13 節，方桶流水號 061 該列）：「相關文件紀錄能證實近年來對訓練成果轉移及達成的檢討，並有具體佐證資料。」文件以「跨近期年度的訓練成果移轉與達成分析檢討」為核心主題，直接回應官方要求。"
    },
    "genre_mechanics": {
      "status": "pass",
      "evidence": "文件為analysis/evaluation report焦點在訓練移轉與達成檢討，決策問題與範圍明確，來源/樣本/納入準則完整，指標定義與分母公式在「名詞與計算定義」提供，完整樣本數據與計算過程在表 T2-T12，區段/趨勢/差距分析在「跨期趨勢與群組分析」，詮釋與數據限制在「限制」一節，發現、原因與證據強度在「發現」一節，可行建議、角色、截止日期與後續指標在「改善與後續追蹤表 T9」，合成聲明與 REAL 替換清單在「需要之真實事實與替換路徑」，證據索引透過「表 T11 圖表定位清單」提供。"
    },
    "title_negative_neighbor": {
      "status": "pass",
      "evidence": "明確界斷鄰近方桶 I12-E04 與 I13-E02；不與受訓志工事後資訊/課程選擇內容可直接替換；具「合成／真實界線」說明；明確退件門檻：移除跨期分母表與佐證分層即可交付 062/063，退化為操作手冊、未填寫的表單、純行動計畫、機制運作報告、滿意度報告或證據取得流程即為退件。"
    },
    "completeness": {
      "status": "pass",
      "evidence": "檢核所需之項目均已備齊：決策問題與範圍、來源/樣本/納入準則、指標定義與分母公式、完整樣本數據與計算過程、區段/趨勢/差距分析、詮釋與數據限制、發現、原因與證據強度、可行建議、角色、截止日期與後續指標、合成聲明與 REAL 替換清單、證據索引/審查/版本（透過「名詞與計算定義」字典、表 T11 圖表定位清單、表 T9 改善追蹤表等提供）。"
    },
    "calculation_consistency": {
      "status": "pass",
      "evidence": "嵌套檢核通過：G⊆E⊆D⊆C⊆A（例：第一期：6≤15≤24≤32≤40）與 F⊆B⊆A（29≤36≤40）；所有率計算與表 T2 完全一致；合併列 A 40+48+30=118、D 24+32+18=74、E 15+22+11=48、G 6+10+5=21；各期率正確：第一期 評量完成率 90.0%、主要應用率 62.5%、非自述佐證占率 40.0%；第二期 93.8%、68.8%、45.5%；第三期 93.3%、61.1%、45.5%；合併 92.4%、64.9%、43.8%。"
    },
    "synthetic_real_boundary": {
      "status": "pass",
      "evidence": "文件開首「合成／真實界線」說明全部均為 SAMPLE/SYNTHETIC；所有成效標記為「非協會實績、非因果、非 TTQS 分數」；「需要之真實事實與替換路徑」清單登錄待取得真實來源；文末免責聲明明確：「本文件為合成示範候選，不是正式評核結果，也不是協會實際辦訓或達成成果之證明」。"
    },
    "traceable_evidence_limitations": {
      "status": "pass",
      "evidence": "限制明確列出：樣本極小、自選偏差、佐證層級不均、期間與成熟度不一、無對照組、合成性質；每一發現皆註明「以合成示範資料陳述，不主張協會實際達成績效」；證據來源透過 表 T7、T9、T11 等可追蹤；T+180 規則與各期成熟度界限說明清晰。"
    }
  },
  "math_recalculation": "All calculations verified consistent with defined formulas and nested set constraints. No recalculation needed. Key rates: 第一期 評量完成率 90.0%、主要應用率 62.5%、非自述佐證占率 40.0%；第二期：93.8%、68.8%、45.5%；第三期：93.3%、61.1%、45.5%；合併：92.4%、64.9%、43.8%。",
  "synthetic_truth_boundary": "Compliant: synthetic declaration present at document onset; all data labeled SAMPLE/SYNTHETIC; REAL replacement list acknowledges current lack of verified association sources; no synthetic fact presented as real; disclaimer at document end confirms synthetic nature.",
  "negative_neighbor_and_title_blind": "Compliant: explicit boundary keeping from I12-E04 and I13-E02; structure and calculations specific to I13-E01; would not be reusable unchanged for neighboring requirements; clearly distinguishes from trainee-facing materials and generic course-selection content.",
  "reviewer_conclusion": "The candidate document presents a complete, well-structured synthetic demonstration analysis of training transfer and attainment review (I13-E01). All required elements are present: decision question and scope, source/sample criteria, indicator definitions with denominators and formulas, full sample data and worked calculations, segment/trend/gap analysis, interpretation and data limitations, findings with evidence strength, actionable recommendations with roles/due dates/metrics, synthetic declaration, and REAL replacement list. The synthetic/real boundary is properly maintained throughout. Calculations are consistent with nested set constraints. Negative neighbor distinction from I12-E04/I13-E02 is clear. Verdict: PASS."
}
